export type ChatContext = {
	/**
	 *  Files previously written via `upload_chat_attachment`. The
	 *  runtime renders these as a `Files attached:` list in the
	 *  preamble; the runner reads them from the worktree cwd.
	 */
	attachments?: ChatAttachmentRef[],
	/**
	 *  Where the user invoked chat from in the UI, e.g.
	 *  `jobs/01H…`, `repos/myrepo`, `settings/models`. Free-form so
	 *  the UI can evolve its routes without a wire change. Renders
	 *  into the preamble as a "User is viewing:" line so the model
	 *  can ground answers to the active surface.
	 */
	ui_location?: string | null,
	/**
	 *  Currently-selected text in the UI (editor selection, log
	 *  snippet, diff hunk). Optional and bounded by the UI to a
	 *  sensible size before sending — the runtime does not truncate.
	 */
	selection?: string | null,
	/**
	 *  Named or ad-hoc prompt snippets the user opted in for this
	 *  turn (saved from a prompt library, project conventions, etc.).
	 *  Each entry is rendered as its own block in the preamble; the
	 *  UI is responsible for ordering.
	 */
	user_prompts?: UserPromptSnippet[],
	/**
	 *  Other jobs the user wants folded into this turn's preamble.
	 *  Each entry opts into the referenced job's spec files and/or
	 *  recent history snapshot. Restricted server-side to refs whose
	 *  repo matches the active job's — cross-repo refs return
	 *  `InvalidArgument`. Additive: an empty vec preserves the
	 *  pre-`job_refs` preamble shape exactly.
	 */
	job_refs?: JobContextRef[],
};

/**
 *  One persisted row in `chat_messages`. The single conversation
 *  every transport reads and writes — see `DOCS/JOB-CHAT.md` "Data
 *  model".
 * 
 *  `run_id` is currently typed as `Option<String>` because the
 *  JOB-WORKFLOW (B) Job/Run split (and the `RunId` newtype it
 *  introduces) has not landed yet; the SQL column is already nullable
 *  and rows minted before (B) leave it NULL. Once (B) lands, this
 *  field swaps to `Option<RunId>` without a wire-format change — the
 *  transparent newtype serialises as the same JSON string.
 * 
 *  `external_id` is NOT NULL on the SQL side for Telegram and Slack
 *  rows (the partial UNIQUE index enforces ingest idempotency for
 *  those transports); the wire type carries `Option<String>` because
 *  web, CLI, and supervisor rows leave it NULL and the column is
 *  generic. The invariant is owned by the runtime insert path, not
 *  the wire type.
 */
export type ChatMessage = {
	id: MessageId,
	job_id: JobId,
	run_id: string | null,
	transport: ChatTransport,
	external_id: string | null,
	thread_key: string | null,
	author: string,
	role: ChatRole,
	body: string,
	/**
	 *  Transport-specific extras (attachments, formatting, delivery
	 *  receipts written by outbound forwarders). Carried as the raw
	 *  JSON text exactly as stored in the SQL `metadata_json` column
	 *  — keeping the field a `String` avoids pulling `serde_json`
	 *  into `codeless-types`, which has to compile for mobile (R1).
	 *  Callers that need a structured view parse it themselves on
	 *  arrival; the substrate stays opaque.
	 */
	metadata_json: string | null,
	created_at: UnixMillis,
};

/**
 *  Mode the chat composer is in for a given turn. Default `Work`
 *  keeps the existing footer/job chat behaviour; `Spec` flips the
 *  preamble to "you are authoring the job spec" and clamps tool
 *  access so the agent cannot accidentally edit repo source.
 */
export type ChatMode = "work" | "spec";

/**
 *  Speaker class of a chat row. Mirrors the role column on
 *  `chat_messages` and overlaps deliberately with
 *  `AssistantMessageRole` so the same CommonChat renderer can paint
 *  both surfaces. Kept as its own enum (rather than reusing the
 *  assistant one) because the two surfaces evolve independently —
 *  JOB-CHAT.md is explicit that the per-Job chat is not the
 *  `/assistant` surface, even though they look similar in the UI.
 */
export type ChatRole = "user" | "assistant" | "tool" | "system";

/**
 *  Origin surface of a chat row. The wire form is lowercase ASCII on
 *  every transport (JSON, SQLite `transport` column, Telegram/Slack
 *  metadata, log fields) — see `DOCS/JOB-CHAT.md` "Wire-name
 *  convention for `ChatTransport`". Adapters compare values only as
 *  these lowercase strings; never as Rust identifiers, display names,
 *  or human-language synonyms.
 * 
 *  The v0.1 surface is closed at five variants. `Web`, `Cli`, and
 *  `Supervisor` ship with the C1 substrate; `Telegram` and `Slack`
 *  arrive with the first transport adapter. The supervisor agent is
 *  modelled as a transport rather than a role so a single
 *  `(transport, external_id)` self-match could in principle suppress
 *  echo back to a participant — though the actual rule in JOB-CHAT.md
 *  is asymmetric and lives in the bot-core helper, not here.
 */
export type ChatTransport = "web" | "cli" | "telegram" | "slack" | "supervisor";

/**
 *  Best-effort probe result for Claude Code on the host. The host
 *  adapter populates this at server boot when `--enable-claude` is
 *  passed; the UI consumes it on the settings → Models surface to
 *  render an actionable hint ("Install Claude Code", "Run
 *  `claude auth login`", "Ready"). `authenticated` is `Some(true)` /
 *  `Some(false)` only when the probe could parse a definite answer;
 *  `None` means the binary exists but the wrapper did not report
 *  auth state within the probe budget, so the UI should fall back to
 *  the neutral "binary detected" hint.
 */
export type ClaudeStatus = {
	binary_path: string,
	version: string | null,
	authenticated: boolean | null,
};

/**
 *  Adds a free-form comment to a review without changing its status.
 *  `Pending` reviews stay pending so the operator can keep iterating;
 *  the final approve / stop call lands a terminal status transition.
 */
export type CommentReviewArgs = {
	review_id: ReviewId,
	comment: string,
};

/**
 *  `assistant.confirmAction`. Dispatch the tool call proposed by a
 *  prior `Assistant`-role message whose `meta_json` carries an
 *  `AssistantActionCard`. The runtime executes the same `RpcServer`
 *  method a direct caller would invoke, then writes a trailing
 *  `Tool`-role message with a structured result summary so the
 *  transcript captures both the proposal and what happened. The
 *  proposal row's `meta_json.status` is flipped to `confirmed` or
 *  `failed` in the same transaction so the UI does not have to keep
 *  confirm/cancel buttons live after the click.
 * 
 *  `NotFound` for an unknown `message_id`; `InvalidArgument` when the
 *  message is not an action card or is no longer pending (already
 *  confirmed/cancelled — confirming twice is a no-op the UI shouldn't
 *  be able to trigger, but the server is the source of truth).
 */
export type ConfirmAssistantActionArgs = {
	thread_id: AssistantThreadId,
	message_id: AssistantMessageId,
};

/**
 *  Result of an action confirmation. `card` is the proposal row after
 *  the status flip — the UI swaps it in place to retire the buttons.
 *  `tool_message` is the newly-appended `Tool`-role row carrying the
 *  structured outcome (`content` is the human summary; `meta_json`
 *  carries the original action + a serde-tagged result payload so the
 *  renderer can show e.g. a list of jobs without re-querying).
 */
export type ConfirmAssistantActionResult = {
	card: AssistantMessage,
	tool_message: AssistantMessage,
};

/**
 *  USD amount in integer cents. Per SCOPE.md "All money is stored as
 *  `INTEGER` cents-USD (no floats, no rounding surprises)." Conversions
 *  to display strings live in the UI layer, not here.
 */
export type CostCents = number;

/**
 *  `assistant.createThread`. The title is optional at create time so
 *  the UI can mint a thread on first message and let the assistant
 *  pick a title later (or leave the default). Empty / all-whitespace
 *  titles are normalised to the default "New thread" so listings
 *  never render a blank rail entry.
 * 
 *  `persona_id` is required (PS5 -- `DOCS/PLUGIN-SUBSTRATE.md` item
 *  5): a thread declares its persona at creation and the runner reads
 *  `system_prompt`, `allowed_tools`, `default_model_family`, and
 *  `default_attachments_policy` off that row at agent-call time. The
 *  substrate doc explicitly forbids a silent default, so an omitted
 *  or empty `persona_id` returns `InvalidArgument`; an unknown
 *  persona returns `NotFound`. The persona is immutable for the
 *  thread's lifetime once persisted.
 */
export type CreateAssistantThreadArgs = {
	title?: string | null,
	persona_id: string,
};

/**
 *  `assistant.deleteThread`. Cascades through `assistant_messages` and
 *  `assistant_attachments` via the SQLite FK; the on-disk
 *  `<codeless-data>/threads/<thread_id>/` directory is removed in the
 *  same call so attachments do not outlive the row. Idempotent —
 *  `NotFound` is returned for an unknown id so the UI can distinguish
 *  "already deleted" from "delete failed".
 */
export type DeleteAssistantThreadArgs = {
	thread_id: AssistantThreadId,
};

/**
 *  What detach does when jobs are still running against the workspace.
 *  `Refuse` is the safe default: detach nothing, return the running
 *  `JobId`s so the UI can prompt. `Stop` cancels them first.
 *  `LeaveRunning` detaches only the editor surface — runners keep
 *  their private worktree-scoped `fs.*` handle, but the editor side
 *  loses access until re-attach.
 */
export type DetachPolicy = "refuse" | "stop" | "leave-running";

export type DetachWorkspaceArgs = {
	repo_id: RepoId,
	on_running_jobs: DetachPolicy,
};

/**
 *  Edit the body of a proposed scope patch in-place. Mirrors `codeless
 *  patches edit` but without the `$EDITOR` round-trip — the UI submits
 *  the new markdown directly. The runtime re-parses the supplied
 *  payload as a single proposal block; the parsed proposal must have
 *  the same `id` as `patch_id`. `body` is the *complete* rendered
 *  proposal as it would appear in `DOCS/SCOPE-PROPOSED.md` (i.e.
 *  `Proposal::render`'s output), so the round-trip stays loss-free.
 * 
 *  Editing does not produce a commit — the operator typically follows
 *  up with `approve_scope_patch`. Idempotency applies in the same
 *  shape: editing an already-resolved patch returns `AlreadyResolved`.
 */
export type EditScopePatchArgs = {
	repo_id: RepoId,
	patch_id: ScopePatchId,
	/**
	 *  Full rendered proposal block as it would appear in the queue
	 *  file (heading + bulleted metadata + `### Rationale` + `### Body`
	 *  sections). Validated server-side; an unparseable buffer returns
	 *  `InvalidArgument`.
	 */
	rendered: string,
};

/**
 *  One row from the `events` table. Variants are tagged by the
 *  `events.type` wire label; payload fields are flattened into the
 *  JSON object stored in `events.payload`.
 * 
 *  Each variant carries an explicit `#[serde(rename = "...")]` rather
 *  than a container-level `rename_all = "kebab-case"`: specta-serde
 *  (0.0.10) propagates `rename_all` to variant fields too, which
 *  silently kebab-cases `task_id` etc. in generated TypeScript and
 *  drifts from serde's actual JSON output (where struct fields stay
 *  snake_case unless `rename_all_fields` is also set, and the specta
 *  macro does not forward that attribute). Explicit per-variant
 *  renames keep the wire label visible at the variant site and dodge
 *  the divergence.
 * 
 *  `task-enqueued` carries `depends_on` from day one per SCOPE.md Rule 4:
 *  the schema must describe DAG state even while Phase 2 executes
 *  linearly, so the wire format does not need a breaking change when
 *  topological scheduling lands later.
 */
export type Event = { type: "repo-added"; repo_id: RepoId } | { type: "repo-removed"; repo_id: RepoId } | { type: "repo-updated"; repo_id: RepoId } | { type: "job-queued"; job_id: JobId; repo_id: RepoId } | { type: "job-promoted"; job_id: JobId } | { type: "job-started"; job_id: JobId } | { type: "job-completed"; job_id: JobId } | { type: "job-stopped"; job_id: JobId; reason: StopReason } | { type: "job-failed"; job_id: JobId } | 
/**
 *  Job moved from `Running` (or `AwaitingReview`) to `Paused`.
 *  Distinct from `JobStopped`: a paused row is *expected* to
 *  be resumed via `resume_job`; the captured per-stage
 *  `Stage.session_id` is the resume handle. Emitted by the
 *  cap-watcher when a cost/wall-clock cap trips on a stage
 *  that has a captured session id (resumable) and by the
 *  `pause_job` RPC. The `reason` distinguishes user intent
 *  from cap-tripped pauses so dashboards and chat dividers
 *  can render the right copy.
 */
{ type: "job-paused"; job_id: JobId; reason: StopReason } | 
/**
 *  User-initiated re-queue of a terminal-but-recoverable job
 *  (A0 — intra-stage session continuation). The job's branch,
 *  worktree, and captured per-stage `Stage.session_id` survive;
 *  the next claude task passes the session id as
 *  `CliCfg::resume_id` so the agent continues the same
 *  conversation rather than re-deriving. Distinct from
 *  `JobPromoted` (which is for `Draft -> Queued`) and `JobQueued`
 *  (which is for fresh submit) so the dashboard and chat can
 *  render a "resumed" divider rather than treating it as a new
 *  run.
 */
{ type: "job-resumed"; job_id: JobId; 
/**
 *  The reason the job had stopped before the resume. `None`
 *  when the row had no `stop_reason` recorded (a fresh
 *  resume of a never-stopped row is a programming error;
 *  the RPC enforces it).
 */
previous_reason?: StopReason | null; 
/**
 *  Free-text identifier for the surface that initiated the
 *  resume. The first consumer is the Slack control plane,
 *  which sets this to `"slack"` (vs. `"operator"` for direct
 *  UI/CLI/RPC, `"assistant"` for the assistant-tool path,
 *  etc.) so audit and dashboard surfaces can distinguish a
 *  phone-driven resume from a keyboard-driven one. `None`
 *  preserves the historical event shape; older replayed
 *  events deserialize unchanged.
 */
actor?: string | null } | 
/**
 *  `reset_job` returned a stuck job (`Queued` whose driver kept
 *  failing, or a terminal `Failed` / `Stopped`) to an editable
 *  `Draft`. The captured worktree was reaped (best-effort) and
 *  `worktree_path` / `stop_reason` / `ended_at` were cleared.
 *  Distinct from `JobQueued` and `JobPromoted` so the dashboard
 *  can render a "reset to draft" divider rather than treating the
 *  row as a new submission. `previous_status` is the state the
 *  row held immediately before the reset so subscribers can
 *  distinguish a driver-give-up recovery from a manual rewind of
 *  a completed-but-failed run.
 */
{ type: "job-reset"; job_id: JobId; previous_status: JobStatus } | { type: "stage-started"; stage_id: StageId; job_id: JobId; 
/**
 *  0-based position of this stage in the template's `stages:`
 *  list. Carried on the wire so subscribers can persist
 *  `Stage` rows without re-parsing the YAML.
 */
ordinal?: number; 
/**
 *  Title of the stage (the YAML's `stages:` entry, with any
 *  `REVIEW ` prefix preserved). Same source of truth the UI
 *  already uses; persisted on the `Stage` row.
 */
name?: string; 
/**
 *  Per-stage persona override resolved at job-submit
 *  (D1, D5). `None` means the stage inherits the job-level
 *  persona; the StageRecorder writes this verbatim onto
 *  `stages.persona_id` so a per-stage handover and a re-run
 *  reproduce the same binding. Defaults to `None` so older
 *  events from the persisted bus replay still decode.
 */
persona_id?: string | null } | { type: "verify-started"; stage_id: StageId } | { type: "verify-passed"; stage_id: StageId } | { type: "verify-failed"; stage_id: StageId; exit_code: number } | 
/**
 *  One layered verify gate started running. Paired with
 *  `verify-step-passed`, `verify-step-failed`, or
 *  `verify-step-skipped`. The outer `verify-started` /
 *  `verify-passed` / `verify-failed` envelopes still bracket the
 *  stage's whole verify run; the per-step events let the UI render
 *  a glyph per gate (`○ → ● → ✓` or `!`) instead of a single bit.
 */
{ type: "verify-step-started"; stage_id: StageId; 
/**
 *  0-based index into the stage's `verify:` list. The
 *  list ordering is the contract; the recorder pins
 *  per-step rows by `(stage_id, step_index)`.
 */
step_index: number; name: string } | { type: "verify-step-passed"; stage_id: StageId; step_index: number; name: string; 
/**
 *  Wall-clock duration of the step's shell invocation, in
 *  milliseconds. Surfaced in the UI's per-gate row so a slow
 *  gate is visible without opening the log.
 */
duration_ms: number } | { type: "verify-step-failed"; stage_id: StageId; step_index: number; name: string; exit_code: number; 
/**
 *  Last ~16 lines of merged stdout+stderr from the step. Kept
 *  short on the wire so the UI doesn't have to fetch a separate
 *  log blob to render the failure preview.
 */
tail: string } | 
/**
 *  A verify step that did not run because a prior step in the same
 *  stage already failed. Emitted (rather than silently omitted) so
 *  the UI can render a `-` or grey-out glyph instead of leaving the
 *  row blank, per SCOPE.md operator-visibility hard rule.
 */
{ type: "verify-step-skipped"; stage_id: StageId; step_index: number; name: string; 
/**
 *  Today the only reason is `"prior-gate-red"`; carried as a
 *  string so future reasons (e.g. timeout, cancelled) can land
 *  without a wire-format change.
 */
reason: string } | { type: "stage-completed"; stage_id: StageId; status: StageStatus; 
/**
 *  Coarse classification when `status = Failed`. The
 *  StageRecorder writes this onto `stages.failure_class`
 *  in the same SQL update as `status`. `None` for
 *  `Passed` and for replayed events from before the field
 *  existed (which decode unchanged via `serde(default)`).
 */
failure_class?: FailureClass | null; 
/**
 *  Short human-readable failure description paired with
 *  `failure_class`. Truncated to ~200 chars at the emit
 *  site. `None` for `Passed` and for legacy events.
 */
failure_detail?: string | null } | 
/**
 *  Heartbeat the runner emits while the closing-trio gate is
 *  holding a stage open. Surfaces to the UI which trio rails the
 *  gate is still waiting on (e.g. `["docs", "git"]`) so an
 *  operator can tell "the gate is working" from "the gate is
 *  stuck" without watching server logs. Emitted on the first
 *  poll where the gate is still `Pending`, then periodically
 *  (~10s) until the gate resolves, fails, or times out.
 * 
 *  `elapsed_ms` is wall time since the gate started waiting;
 *  it crosses the configured max-wait (5 min) the runner emits
 *  `StageCompleted { Failed, failure_class: RunnerError }` with
 *  a `trio gate timed out: …` detail and the stage routes
 *  through the same auto-bypass path as any other stage failure.
 */
{ type: "stage-trio-gate-waiting"; stage_id: StageId; waiting_on: TodoKind[]; elapsed_ms: number } | 
/**
 *  First-and-only-time capture of the runner-supplied session id
 *  for this stage. Emitted by `StageRecorder` the first time a
 *  task on the stage reports a non-empty `RunResult.session_id`;
 *  subsequent tasks with a session id on the same stage do not
 *  re-emit. The recorder pins the same value onto
 *  `stages.session_id` in SQLite so the observation survives
 *  session boundaries.
 */
{ type: "stage-session-captured"; stage_id: StageId; session_id: string } | 
/**
 *  The stage's warm session was archived (idle timeout elapsed) and
 *  the next user message against the stage transparently opened a
 *  fresh session preceded by a handover document. Emitted exactly
 *  once per session boundary so the UI can render an inline divider
 *  (`prior session archived; resumed with handover`) without
 *  polling for state changes. `prior_session_id` is the value that
 *  was on `stages.session_id` at archive time; the new session's
 *  id arrives later via `StageSessionCaptured`.
 */
{ type: "session-archived-then-resumed"; stage_id: StageId; prior_session_id: string } | { type: "task-enqueued"; task_id: TaskId; stage_id: StageId; depends_on: TaskId[] } | { type: "task-started"; task_id: TaskId } | { type: "tool-call"; task_id: TaskId; tool: string; args_json: string } | { type: "tool-approval-requested"; task_id: TaskId; tool: string; args_json: string } | { type: "ai-token"; task_id: TaskId; delta: string } | { type: "ai-message-complete"; task_id: TaskId; input_tokens: number; output_tokens: number; cost_cents: CostCents } | { type: "task-completed"; task_id: TaskId; status: TaskStatus } | 
/**
 *  A new sub-step appeared on a running task — either the runner
 *  emitted a `TodoWrite`-equivalent tool call (`kind = Runner`) or
 *  the runtime injected one (`kind` is one of `Checks` / `Docs` /
 *  `Git` for the closing trio, or `Planner` for the future
 *  stage-level pre-declared path). See `DOCS/JOB-UI.md` "Todo rows
 *  (nested under a tick)" for the UI contract — the row's glyph
 *  flips `○ → ● → ✓` as `TodoUpdated` / `TodoCompleted` arrive.
 */
{ type: "todo-added"; todo_id: TodoId; task_id: TaskId; ordinal: number; title: string; kind: TodoKind } | 
/**
 *  Status transition on an existing todo. Carried as a separate
 *  event from `TodoCompleted` so an intermediate `Pending →
 *  InProgress` flip can light up the `●` glyph without faking a
 *  completion. `TodoCompleted` is the dedicated terminal event so
 *  the stage-completion gate (the part that holds back
 *  `StageCompleted` until the trio is resolved) can subscribe to
 *  one event type instead of inspecting every `TodoUpdated`.
 */
{ type: "todo-updated"; todo_id: TodoId; status: TodoStatus } | 
/**
 *  Terminal transition: `Done`, `Skipped`, or `Failed`. Pairs with
 *  `TodoUpdated` — the runtime emits `TodoUpdated` for non-terminal
 *  flips and `TodoCompleted` for terminal ones, so subscribers can
 *  pick the granularity they care about.
 * 
 *  `failure_detail` is set only when `status == Failed` and carries
 *  a human-readable reason (e.g. "write handover.json: Permission
 *  denied", "git commit failed: nothing to commit, working tree
 *  clean"). The closing-trio gate surfaces this string into the
 *  stage's `failure_detail` so the UI shows *which rail* failed
 *  and *why* instead of a generic "stage failed" — the previous
 *  silent gate-hang behaviour (the docs rail going `Failed` while
 *  the gate polled forever) is exactly what this field is here to
 *  prevent.
 */
{ type: "todo-completed"; todo_id: TodoId; status: TodoStatus; failure_detail?: string | null } | { type: "review-requested"; review_id: ReviewId; stage_id: StageId } | { type: "review-approved"; review_id: ReviewId } | { type: "review-commented"; review_id: ReviewId; comment: string } | { type: "review-stopped"; review_id: ReviewId } | 
/**
 *  `template.yaml` for the job changed in SQLite. Emitted by
 *  `update_job_template` (user edits from the Spec pane) and by
 *  `resync_template_from_disk` at the head of `start_job` /
 *  `resume_job` when a chat-driven filesystem edit lands in the
 *  DB. Subscribers — the Spec pane, the chat's footer banner —
 *  use this as a refetch signal; the new YAML is not on the
 *  wire because the Spec pane already fetches it through
 *  `read_job_file` / `get_job`.
 */
{ type: "job-template-updated"; job_id: JobId } | 
/**
 *  An attached workspace's canonical root is no longer reachable
 *  (the directory was deleted, the volume unmounted, the symlink
 *  target vanished, etc). Emitted exactly once per transition by the
 *  30s liveness sweep in `codeless-runtime::workspace_liveness`; the
 *  follow-up `WorkspaceRecovered` event fires when the path comes
 *  back. The UI uses the pair to flip a per-workspace badge in the
 *  sidebar without polling.
 * 
 *  `fs_root` is the canonical path as registered in
 *  `attached_workspaces.fs_root_canonical`. `reason` is a short
 *  machine-readable tag (`"missing"`, `"not-a-directory"`,
 *  `"io-error"`) — string-typed rather than a wire enum so a new
 *  failure mode can land without an enum-bump on every shell.
 */
{ type: "workspace-unhealthy"; repo_id: RepoId; fs_root: string; reason: string } | 
/**
 *  Paired with `WorkspaceUnhealthy`. Fires the next sweep after the
 *  path resolves to a directory again.
 */
{ type: "workspace-recovered"; repo_id: RepoId; fs_root: string } | 
/**
 *  A supporting file under `.codeless/jobs/<name>/` was written
 *  or deleted. `filename` is the basename (e.g. `SCOPE.md`),
 *  not a full path, so subscribers don't have to know about
 *  repo layout. Emitted by `write_job_file` and `delete_job_file`.
 *  Chat-driven raw-`Edit`/`Write` edits do not emit this — the
 *  agent is told disk is the source of truth and the Spec pane
 *  refreshes on the next `JobTemplateUpdated` (run-time resync)
 *  or on user navigation.
 */
{ type: "job-file-updated"; job_id: JobId; filename: string } | 
/**
 *  A REVIEW stage proposed a rulebook patch (Step 4 of the
 *  SESSION-MUTABLE-SCOPE ramp, shadow mode). The full proposal
 *  body lives in `DOCS/SCOPE-PROPOSED.md`; this event carries
 *  identifiers and discriminants only so consumers can answer
 *  the kill-criterion query ("how many proposals in the last K
 *  REVIEW stages, how many had a predicate, how many landed")
 *  without re-reading the file. Decisions Q7 records why this
 *  is an event rather than a row in a new SQLite table (R4 —
 *  SQLite is source of truth, no new persistence store).
 * 
 *  `evidence_stage_id` is `Some` only for `Loosen` and `None`
 *  for `Tighten`; `has_predicate` is the dual signal for
 *  `Tighten`. Carrying both as separate fields (rather than
 *  merging into a single variant per kind) keeps the SSE wire
 *  label single — one envelope shape per event type — which
 *  the existing UI subscriber assumes.
 *  Layer-1 diff-verify pre-check result for a REVIEW stage —
 *  the first half of Surface A's gate diagnostics. Emitted by
 *  `template_runner` alongside the existing `tracing::info!` /
 *  `tracing::warn!` lines that report the same outcome; the
 *  logs stay for operator debugging, the event carries the
 *  structured form the UI panel renders. `Pass` and `Fail`
 *  carry the resolved path lists rather than a boolean so the
 *  panel can name the exact set; `Skipped` and `NothingToVerify`
 *  are distinct on the wire so the panel can tell a setup gap
 *  apart from a clean-baseline handover (see
 *  `review_gate::PreCheckOutcome` for the variant contract).
 */
{ type: "review-pre-check"; stage_id: StageId; outcome: PreCheckOutcome } | 
/**
 *  Final REVIEW-gate verdict, including the runtime's own
 *  `AutoFail` cases (pre-check rejected, sentinel unparseable,
 *  scope-patch validation failed). Emitted exactly once per
 *  REVIEW stage that reaches a terminal verdict; the
 *  matching `tracing` call on `template_runner` keeps the
 *  human-readable log line. Pairs with `ReviewPreCheck` —
 *  when the pre-check auto-fails, both events fire (pre-check
 *  with `Fail`, verdict with `AutoFail`) so the panel sees
 *  the same two-phase shape it does for the model-driven path.
 */
{ type: "review-verdict"; stage_id: StageId; verdict: ReviewVerdict } | { type: "scope-patch-proposed"; stage_id: StageId; review_id: ReviewId; patch_id: ScopePatchId; kind: ScopePatchKind; target: ScopePatchTarget; 
/**
 *  Repo-relative path of the file the proposal targets.
 *  Carried on the wire so subscribers can render the path
 *  without fetching the proposal body.
 */
target_path: string; evidence_stage_id: StageId | null; has_predicate: boolean } | 
/**
 *  Operator approved a proposed scope patch through the UI. Emitted
 *  after the approval commit lands so cross-window subscribers can
 *  invalidate their patch-inbox caches and link to the resulting
 *  commit without a follow-up RPC. Same shape considerations as
 *  `ScopePatchProposed` — mobile-safe, no enrichment that requires
 *  host-only types.
 */
{ type: "scope-patch-approved"; stage_id: StageId; review_id: ReviewId; patch_id: ScopePatchId; kind: ScopePatchKind; target: ScopePatchTarget; target_path: string; 
/**
 *  SHA of the human-authored approval commit produced by
 *  `approve_scope_patch`. The UI links the inbox row to a
 *  `commit/<sha>` route off this field.
 */
commit_sha: string } | 
/**
 *  Operator rejected a proposed scope patch through the UI. Pairs
 *  with `ScopePatchApproved`; same cross-window invalidation use
 *  case.
 */
{ type: "scope-patch-rejected"; stage_id: StageId; review_id: ReviewId; patch_id: ScopePatchId; kind: ScopePatchKind; target: ScopePatchTarget; target_path: string; commit_sha: string } | 
/**
 *  A stage failed under a job-level `AutoBypassPolicy` and the
 *  runtime auto-bypassed the failure to keep the job moving
 *  (Surface F, `DOCS/AUTO-BYPASS-DECISIONS.md` Q1/Q4). Emitted
 *  by the stage-failed handler in the same commit that writes
 *  `stages.bypassed_at` / `stages.bypassed_reason`; the
 *  corresponding `tracing` line stays for operator debugging
 *  while this event carries the structured form the UI gate
 *  panel reads. Deliberately a distinct variant from
 *  Surface E's operator-clicked `StageBypassed` so the panel
 *  can render `bypassed by policy: <name>` vs
 *  `bypassed by operator` without inspecting the reason
 *  string (Q6 "Event reuse").
 * 
 *  `policy_name` is the stable name returned by
 *  `AutoBypassPolicy::policy_name()` — one of the five preset
 *  labels or the literal `"Custom"`. `comment_used` is the
 *  canned (or operator-supplied) guidance string that was
 *  threaded into the next stage's prompt; it is carried on
 *  the wire so subscribers can render the comment without
 *  re-resolving the policy and to keep the audit trail intact
 *  if a future preset string is reworded (Q4
 *  wording-revision policy). `applied_at` mirrors
 *  `stages.bypassed_at` and is the timestamp the recorder
 *  stamped on the row.
 */
{ type: "stage-auto-bypassed"; stage_id: StageId; policy_name: string; comment_used: string; applied_at: UnixMillis } | 
/**
 *  `set_job_policy` replaced (or cleared) the job's
 *  `auto_bypass_policy`. Emitted only when the value actually
 *  changes — a same-policy call is a no-op success that publishes
 *  nothing, keeping cross-window invalidation traffic bounded
 *  (`DOCS/AUTO-BYPASS-DECISIONS.md` Q5 "Idempotency"). `policy_name`
 *  mirrors `AutoBypassPolicy::policy_name()` (one of the five preset
 *  labels or the literal `"Custom"`), or `None` when the policy was
 *  cleared. Subscribers refresh their per-job badge / submit-form
 *  state from this event without re-fetching the whole row.
 */
{ type: "job-policy-changed"; job_id: JobId; policy_name?: string | null } | 
/**
 *  `assistant_threads.updated_at` advanced — a message was appended,
 *  an action card was confirmed/cancelled, or an attachment was
 *  uploaded. The `/assistant` thread-list rail subscribes to this
 *  envelope as its re-sort signal so the order stays live without
 *  the focusStore `refreshTick` polling counter the rail used to
 *  rely on (`DOCS/SCOPE-ASSISTANT-PARITY.md` §W1). The same envelope
 *  also lets the footer composer recount pending cards and the open
 *  thread view re-list messages when a touch arrives from another
 *  surface — every assistant pane keys off the same channel.
 * 
 *  Published with the synthetic `bus_job_id = JobId(thread_id.0)`
 *  the planner already uses (`assistant_planner.rs`), so a
 *  `{ scope: "job", job_id: thread_id }` subscriber sees the touch
 *  alongside the `AiToken` / `AiMessageComplete` envelopes for the
 *  same turn. Subscribers that need touches across every thread
 *  (the rail) subscribe with `scope: "all"`.
 */
{ type: "assistant-thread-touched"; thread_id: AssistantThreadId } | 
/**
 *  A row was appended to `chat_messages`. Published by
 *  `post_job_message` immediately after the INSERT lands, so every
 *  transport adapter (web UI, Telegram, Slack, CLI, supervisor)
 *  sees the same fan-out signal regardless of which surface
 *  originated the message. The full `ChatMessage` rides on the
 *  envelope so subscribers can render without a follow-up read;
 *  the asymmetric echo-suppression rule in `DOCS/JOB-CHAT.md`
 *  "Transport adapters" lives in the bot-core helper, not in the
 *  event payload — every adapter sees every append and decides
 *  per-message whether to forward.
 */
{ type: "chat-message-appended"; job_id: JobId; message: ChatMessage } | 
/**
 *  A `(transport, channel_id, thread_id)` tuple was bound (or
 *  re-bound) to a Job via `bind_chat_thread`. Cross-window
 *  invalidation signal for the web UI's "this Job is also being
 *  watched in #ops-codeless" banner; the Telegram / Slack
 *  adapters do not need it on the inbound path (they look the
 *  binding up directly on each message).
 */
{ type: "chat-binding-created"; transport: ChatTransport; channel_id: string; thread_id: string; job_id: JobId };

/**
 *  Monotonic event index, allocated by `events.cursor INTEGER
 *  AUTOINCREMENT`. Doubles as `Last-Event-ID` over SSE (SCOPE.md
 *  "Catch-up cursor.") — clients send the last seen cursor on reconnect
 *  and the server replays from that point.
 */
export type EventCursor = number;

/**
 *  Envelope written to the `events` table. The `cursor`, `created_at`,
 *  and foreign-key columns are recorded by the runtime; the inner
 *  `Event` is the JSON payload.
 */
export type EventEnvelope = {
	cursor: EventCursor,
	job_id: JobId | null,
	stage_id: StageId | null,
	task_id: TaskId | null,
	created_at: UnixMillis,
	event: Event,
};

/**
 *  Filter passed to `RpcServer::subscribe`. Variants stay coarse on
 *  purpose — per-stage / per-task filtering happens client-side from
 *  the same event stream so the server doesn't need to multiplex N
 *  fine-grained channels.
 */
export type EventFilter = 
// Every event the runtime emits — used by the global event log view.
{ scope: "all" } | 
// Only events tagged with this job (and its stages and tasks).
{ scope: "job"; "job-id": JobId };

/**
 *  Why a stage row ended `Failed`. Persisted on `stages.failure_class`
 *  when `status = Failed`; `None` for `Passed` rows and for legacy
 *  rows written before the column existed. The variant list is the
 *  vocabulary the UI / CLI render from — a coarser set than the
 *  per-site free-text `failure_detail` but precise enough that
 *  dashboards do not have to substring-match on log lines.
 * 
 *  Distinct from `StopReason` (which is per-*job*): a job can halt
 *  for `RunnerCrash` while individual stages along the way have any
 *  of the failure classes below. The two columns coexist; the
 *  stage-level `failure_class` is what the per-stage UI badge reads.
 */
export type FailureClass = 
/**
 *  Layer-1 diff-verify pre-check rejected the prior stage's
 *  handover before the REVIEW model ran. Paired with
 *  `StopReason::ReviewPreCheck` at the job level.
 */
"pre-check-failed" | 
/**
 *  The runner subprocess exited non-zero or the in-process
 *  runner returned `RunnerOutcome::Failed`. The `failure_detail`
 *  carries the runner's reason string (typically the last
 *  non-empty line of its stderr / transcript tail).
 */
"runner-error" | 
/**
 *  REVIEW model emitted `PASS` but the scope-patch validator
 *  rejected the proposed patch (parse failure, predicate
 *  missing on a tightening patch, etc.). The verdict on the
 *  wire is `AutoFail` with the validator's reason.
 */
"review-patch-invalid" | 
/**
 *  REVIEW model emitted `FAIL` as its verdict. The
 *  `failure_detail` carries the model's reason string verbatim.
 */
"review-fail" | 
/**
 *  REVIEW sentinel parser could not extract a verdict from the
 *  handover tail. The `failure_detail` carries the parser
 *  error.
 */
"review-unparseable" | 
/**
 *  Crash recovery flipped a `Running` stage row to `Failed`
 *  because the core process restarted without a clean exit.
 *  Distinct from `RunnerError` so the UI can render
 *  `interrupted by core restart` rather than a runner-side
 *  failure, and the operator knows a plain resume is safe.
 */
"orphan-reap";

/**
 *  Result of `fs_cwd`. The path is the absolute server root the
 *  `fs_*` methods are scoped under. The UI uses this to populate the
 *  explorer when no terminal has yet set a working directory, so the
 *  first browser visit against a real server shows the workspace
 *  contents instead of an empty pane.
 */
export type FsCwdResult = {
	path: string,
};

/**
 *  One entry from a directory listing. `size` and `mtime` are
 *  `Option` because not every filesystem entry has them in the same
 *  way — a symlink to a non-existent target carries no `mtime` from
 *  the target, and a directory's `size` is platform-dependent and not
 *  useful for UI display.
 */
export type FsEntry = {
	name: string,
	kind: FsEntryKind,
	size: number | null,
	mtime: UnixMillis | null,
};

/**
 *  Type of one directory entry. Symlinks are surfaced as their own
 *  kind rather than dereferenced because the explorer UI wants to
 *  distinguish them (different icon, optional target reveal); the
 *  reader follows the link only when the user opens it.
 */
export type FsEntryKind = "file" | "dir" | "symlink";

/**
 *  Paths in every `fs_*` arg are interpreted relative to the
 *  configured server root. The host adapter rejects any path that
 *  escapes the root (`..` segments, absolute paths, symlinks pointing
 *  outside) before touching disk — the wire shape carries no notion
 *  of "outside root" because callers should never need to express it.
 */
export type FsReadDirArgs = {
	path: string,
};

export type FsReadDirResult = {
	entries: FsEntry[],
};

export type FsReadFileArgs = {
	path: string,
};

/**
 *  Result of `fs_read_file`. Binary and over-limit cases will gain
 *  their own variants on this struct when the editor needs them;
 *  the explorer/editor MVP only handles utf-8 text. Files that fail
 *  to decode return `InvalidArgument` for now.
 */
export type FsReadFileResult = {
	content: string,
};

export type FsStatArgs = {
	path: string,
};

/**
 *  Single-entry stat. `kind` is `None` if the path does not exist —
 *  the call still succeeds so callers can probe existence without
 *  catching `NotFound`. Present-entry stats populate `kind`, `size`,
 *  `mtime` from the same source as `fs_read_dir`.
 */
export type FsStatResult = {
	kind: FsEntryKind | null,
	size: number | null,
	mtime: UnixMillis | null,
};

export type FsWriteFileArgs = {
	path: string,
	content: string,
};

/**
 *  Forward lookup on `chat_bindings`: resolve an inbound
 *  `(transport, channel, thread)` to the Job that owns the
 *  conversation. Returns `None` when the channel was never
 *  `/codeless bind`-ed — the adapter treats that as "drop the
 *  message" (the substrate refuses to ingest text the operator has
 *  not pointed at a Job). `thread_id` defaults to the empty-string
 *  sentinel server-side so callers that come from a non-threaded
 *  platform message can pass `None` and still hit the PK row.
 */
export type GetChatBindingArgs = {
	transport: ChatTransport,
	channel_id: string,
	thread_id?: string | null,
};

export type GetChatBindingResult = {
	binding: ChatBinding | null,
};

export type GetJobArgs = {
	job_id: JobId,
};

/**
 *  How the core authenticates to a given repo's remote. Stored as JSON in
 *  the `repos.git_auth` column (SCOPE.md Appendix A). Variant kinds are
 *  stable wire labels; renaming any of them is a breaking change.
 */
export type GitAuth = { kind: "ssh"; key_path: string } | { kind: "token"; env_var: string } | { kind: "github_app"; app_id: string; installation_id: string };

/**
 *  Session-handover contract — see `DOCS/JOB-MODEL.md` "the handover
 *  is the only contract between sessions". A run writes one of these
 *  at `runs/<job_id>/handover.md` in its worktree on completion; the
 *  next session reads it first, before anything else, to decide what
 *  to do next.
 * 
 *  The four sections are deliberately load-bearing:
 *  - `done` is what landed — committed code, decisions ratified by
 *    review, anything the next session does *not* need to redo.
 *  - `next` is what the next session should pick up first; the top
 *    item is the canonical next action.
 *  - `what_you_need_to_know` carries the constraints, invariants, and
 *    gotchas a fresh reader would not infer from the diff alone.
 *  - `open_questions` is for unresolved decisions — the next session
 *    resolves these before it implements anything new.
 * 
 *  A blank handover is forbidden (JOB-MODEL.md): at minimum the
 *  "Done" section must say *something*, even if it's "session aborted
 *  at <stage>, recovery needed".
 * 
 *  `raw_tail` carries everything in the handover body that follows
 *  the four canonical sections. It exists so the
 *  `SCOPE-PATCH-BEGIN` / `SCOPE-PATCH-END` block that the runtime's
 *  `scope_patch_emit` parser reads survives a parse-and-serialise
 *  round-trip of this struct: without it, a UI that displays a
 *  handover (Surface B, per-job patch inbox) and writes the same
 *  struct back would silently drop the proposal. The runtime's
 *  emitter reads the on-disk file body unchanged — `raw_tail` only
 *  guarantees the wire-shape doesn't lose the trailer.
 * 
 *  Adding this field is the wire-schema bump that ships alongside
 *  Surface B: pre-bump JSON has no `raw_tail` key, so the field is
 *  `#[serde(default)]` (deserialises to `None`) for one-way
 *  compatibility with older payloads that never carried it.
 */
export type Handover = {
	done: string[],
	next: string[],
	what_you_need_to_know: string[],
	open_questions: string[],
	raw_tail?: string | null,
};

// One unit of work the user kicked off — see SCOPE.md Appendix A `jobs`.
export type Job = {
	id: JobId,
	repo_id: RepoId,
	status: JobStatus,
	stop_reason: StopReason | null,
	template_yaml: string | null,
	prompt: string | null,
	// Runner kind chosen at submit time (e.g. `"claude"`, `"anthropic"`).
	runner: string,
	branch: string,
	/**
	 *  `in_repo` (default): agent edits the user's local clone.
	 *  `worktree`: agent edits a separate `git worktree add` checkout.
	 */
	workspace_mode: WorkspaceMode,
	/**
	 *  `None` until the worktree has been provisioned. Preserved across
	 *  crashes so a reaper can clean up after a dead leaseholder.
	 *  Always `None` in `in_repo` mode (edits land in the repo itself).
	 */
	worktree_path: string | null,
	cost_cap_cents: CostCents,
	wall_clock_cap_ms: number,
	cost_cents: CostCents,
	/**
	 *  Optional per-job model override forwarded to the runner. `None`
	 *  uses the runner adapter's default. Free-form because each runner
	 *  has its own model catalogue (Claude opus/sonnet/haiku, Copilot
	 *  gpt-5.x, etc.) — validation is the adapter's job, not this layer.
	 */
	model: string | null,
	/**
	 *  Optional per-job permission mode. Only meaningful for runners
	 *  that expose a per-call permission gate (Claude). Wire labels
	 *  match the snake_case form on `claude-wrapper`'s `PermissionMode`:
	 *  `default | accept_edits | plan | bypass`. `None` leaves the
	 *  adapter's headless default (`Bypass` for Claude) in place.
	 */
	permission_mode: string | null,
	/**
	 *  Optional thinking-budget hint. Only meaningful for runners that
	 *  honour it (Claude). Wire labels: `low | medium | high`. `None`
	 *  disables the prompt-trigger prefix that maps to claude's
	 *  "think" / "think hard" / "ultrathink" cues.
	 */
	effort: string | null,
	/**
	 *  Optional persona-derived system prompt composed at submit time.
	 *  When set, the runner factory uses this as the agent's system
	 *  prompt for every stage of the job, overriding the server's
	 *  default. `None` keeps the server-configured default in place so
	 *  jobs submitted without a persona run unchanged. Stored on the
	 *  row so a reboot, resume, or rerun reproduces the same prompt;
	 *  `rerun_job` carries the value forward verbatim.
	 */
	system_prompt: string | null,
	/**
	 *  Persona the user picked at submit time. The composed prompt
	 *  rides on `system_prompt`; this column preserves the lookup key
	 *  so a rerun can reproduce the same agent posture even if the
	 *  persona's body is edited later. `None` means the user submitted
	 *  without picking a persona — the server default applies and a
	 *  rerun keeps that posture. Free TEXT until personas move to a
	 *  server-side table; the FK lands in a later stage.
	 */
	persona_id: string | null,
	/**
	 *  Per-job auto-bypass policy. `None` (the default) preserves the
	 *  existing behaviour: a stage failure under any non-cap reason
	 *  halts the job and waits for operator triage. `Some(policy)`
	 *  pre-authorises the runtime to mark the failed stage
	 *  `Failed`-with-bypass and advance, threading the policy's
	 *  canned (or operator-supplied) guidance into the next stage's
	 *  prompt. Cap breaches (`CostCap`, `WallClock`) ignore the
	 *  policy and halt regardless — see
	 *  `DOCS/AUTO-BYPASS-DECISIONS.md` Q2.
	 */
	auto_bypass_policy: AutoBypassPolicy | null,
	pending_operator_comment: string | null,
	/**
	 *  One-shot flag set by `override_pre_check_and_resume`: the
	 *  operator has acknowledged that the REVIEW stage's diff-verify
	 *  pre-check will fail against the existing handover and wants
	 *  the stage to run anyway. Consumed atomically by the runner on
	 *  the first re-entry into the REVIEW stage so a subsequent run
	 *  (or a later REVIEW stage) does not silently inherit the
	 *  override. `false` is the default and the value on every fresh
	 *  row.
	 */
	precheck_override_once?: boolean,
	started_at: UnixMillis | null,
	ended_at: UnixMillis | null,
	created_at: UnixMillis,
};

/**
 *  One referenced job folded into the chat preamble. Toggles let the
 *  caller pick a spec-only attach (cheap, useful for "what is job B
 *  trying to do"), a history-only attach (cheap-ish, useful for "what
 *  has job B actually done lately"), or both. `history_turn_limit`
 *  bounds the walk before rendering so a long-running job doesn't
 *  silently blow the per-section byte budget on the runtime side.
 *  `None` means "use the runtime default".
 */
export type JobContextRef = {
	job_id: JobId,
	include_spec: boolean,
	include_history: boolean,
	history_turn_limit?: number | null,
};

export type JobDiffArgs = {
	job_id: JobId,
};

/**
 *  Per-file entry in `JobDiffResult.files`. Mirrors the columns the
 *  UI's files-changed tab needs: filename, what kind of change
 *  (added / modified / deleted / renamed), and line counts so the
 *  summary row can show `+N -M` without parsing the patch. `patch`
 *  is the unified-diff body for the single file; clients render it
 *  or skip rendering when the file is binary (in which case `patch`
 *  is the empty string and `is_binary` is true).
 */
export type JobDiffFile = {
	path: string,
	/**
	 *  `"A" | "M" | "D" | "R"` matching `git diff --name-status`.
	 *  Kept as a one-letter string so future status codes (`"C"` for
	 *  copied, `"T"` for type-change) don't break the wire when they
	 *  surface.
	 */
	status: string,
	additions: number,
	deletions: number,
	is_binary: boolean,
	patch: string,
};

/**
 *  Diff of a job's branch against its repo's default branch. Computed
 *  server-side via `git diff` so it works after the worktree has been
 *  reaped (the branch survives in the source repo). Returns
 *  `NotFound` if the job, repo, or branch is gone; `Internal` wraps
 *  `git diff` failures with the stderr the operator can act on.
 */
export type JobDiffResult = {
	/**
	 *  The base ref the diff was computed against (typically the
	 *  repo's `default_branch`). Returned so the UI can label the
	 *  comparison ("vs main").
	 */
	base: string,
	// The job's branch. Same as `codeless/job-<job_id>`.
	head: string,
	files: JobDiffFile[],
};

//Identity of one unit of work scoped to one repo.
export type JobId = string;

/**
 *  Lifecycle states for a job row. String form matches the
 *  `jobs.status` column wire labels in SCOPE.md Appendix A.
 * 
 *  `Draft` is the landing state when a job is submitted with
 *  `start_immediately = false` — the row exists, the user can edit
 *  the spec / docs / handover, but the driver does **not** pick it
 *  up. The user calls `start_job` (or submits with
 *  `start_immediately = true`) to promote `Draft → Queued`. From
 *  there the lifecycle is unchanged.
 */
export type JobStatus = "draft" | "queued" | "running" | "awaiting-review" | "completed" | "failed" | "stopped" | 
/**
 *  User has paused, or a cap tripped on a resumable stage —
 *  the agent's captured `Stage.session_id` is the resume
 *  handle. Distinct from `Stopped`: a paused row is *expected*
 *  to be resumed; a stopped row is the user saying "I'm done."
 *  `resume_job` accepts both. See SCOPE.md hard rule #1
 *  (the stage is the session boundary; within a stage the
 *  runner session is continuous).
 */
"paused";

/**
 *  `assistant.listMessages`. The full transcript for one thread,
 *  ordered by `created_at` ascending so the UI can render top-to-bottom
 *  without an extra sort. Empty result for a freshly-minted thread —
 *  callers distinguish that from a missing thread by issuing the
 *  list against a known id; this method itself does not 404 because
 *  the alternative ("which is empty, the rail entry or this list?")
 *  is the same response for the renderer.
 */
export type ListAssistantMessagesArgs = {
	thread_id: AssistantThreadId,
};

export type ListAssistantMessagesResult = {
	messages: AssistantMessage[],
};

/**
 *  `assistant.listThreads`. No filters in v1 — threads are unscoped
 *  (no per-repo / per-job FK by design, see `AssistantThread`), so the
 *  list is just "every thread the operator has on this host". Returned
 *  rows are ordered by `updated_at` descending so the most recently
 *  touched conversation lands at the top of the rail without the UI
 *  having to re-sort.
 */
export type ListAssistantThreadsArgs = Record<string, never>;

export type ListAssistantThreadsResult = {
	threads: AssistantThread[],
};

/**
 *  Reverse lookup of `chat_bindings`: every `(channel, thread)` on the
 *  given transport that points at the supplied Job. The outbound
 *  forwarder on each transport adapter calls this when a
 *  `ChatMessageAppended` fires for a Job it cares about — the bindings
 *  it returns are the set of platform-side destinations the message
 *  must be forwarded to. The forward direction is the inverse of
 *  `get_chat_binding` (which serves the inbound resolver path).
 */
export type ListChatBindingsForJobArgs = {
	job_id: JobId,
	transport: ChatTransport,
};

export type ListChatBindingsForJobResult = {
	bindings: ChatBinding[],
};

/**
 *  Paginate one Job's chat history newest-first by `created_at` with
 *  the message id as tiebreaker. The web `CHAT` tab calls this on
 *  mount; Telegram and Slack adapters call it on `/codeless bind` to
 *  compose a single condensed "joining mid-thread" summary (full
 *  replay would spam the channel — see `JOB-CHAT.md` "Cold-load").
 * 
 *  `before` is the seek cursor: pass `None` to fetch the most recent
 *  `limit` rows, then pass the oldest returned `MessageId` to walk
 *  further back. The runtime caps `limit` so a runaway caller cannot
 *  pull the whole table in one shot.
 */
export type ListJobMessagesArgs = {
	job_id: JobId,
	before?: MessageId | null,
	limit: number,
};

/**
 *  Returned messages are ordered oldest-first within the returned
 *  page so a UI can render top-to-bottom without sorting. To walk
 *  further back, the caller passes the *oldest* id of this page as
 *  the next `before`.
 */
export type ListJobMessagesResult = {
	messages: ChatMessage[],
};

export type ListJobsArgs = {
	// `None` returns jobs across every repo.
	repo_id: RepoId | null,
};

export type ListJobsResult = {
	jobs: Job[],
};

/**
 *  Snapshot the unresolved patch queue across one or all repos. Powers
 *  Surface C (cross-workspace patch worklist) in
 *  `DOCS/SCOPE-MUTABLE-UI.md`: the editor's standing view across every
 *  repo, independent of any single job. Wraps the same
 *  `scope_patch_queue::load_queue` helper the CLI's `codeless patches
 *  list` uses, lifting the per-entry shape into a mobile-safe DTO
 *  (`ProposedScopePatch`).
 * 
 *  `repo_id = Some(_)` filters to one repo and returns `NotFound` when
 *  that repo row does not exist. `repo_id = None` walks every repo and
 *  concatenates the results — repos with no `DOCS/SCOPE-PROPOSED.md`
 *  contribute zero entries (not an error), and per-repo parse failures
 *  surface as `Internal` so the worklist refuses to half-render under
 *  a corrupted queue file.
 */
export type ListProposedPatchesArgs = {
	/**
	 *  Restrict the walk to a single repo. `None` lists across every
	 *  repo row.
	 */
	repo_id?: RepoId | null,
};

/**
 *  Snapshot the unresolved queue. Ordering is **newest-first by
 *  `proposed_at`**, with `None`-timestamped entries (legacy data
 *  predating the field) sorted last in `id` order. Surface C layers
 *  its 14-day-decay filter and group-by-repo on top of this order; the
 *  runtime does not pre-filter so a "show everything" toggle remains
 *  implementable client-side.
 */
export type ListProposedPatchesResult = {
	entries: ProposedPatchListEntry[],
};

export type ListReposResult = {
	repos: Repo[],
};

/**
 *  Filter for `list_reviews`. All fields compose with AND; `None`
 *  means "do not narrow on this column". Returned rows are ordered by
 *  `requested_at` ascending so a UI can render the oldest pending
 *  review first without re-sorting. The per-job filter joins through
 *  `stages` so the UI's per-job review panel does not need to map
 *  stages to jobs client-side.
 */
export type ListReviewsArgs = {
	job_id: JobId | null,
	stage_id: StageId | null,
	status: ReviewStatus | null,
};

export type ListReviewsResult = {
	reviews: Review[],
};

export type ListWorkspacesResult = {
	workspaces: AttachedWorkspace[],
};

//Identity of one row in `chat_messages` — the per-Job chat substrate from `DOCS/JOB-CHAT.md`. Shared by every transport (web, CLI, Telegram, Slack, supervisor); the ULID is minted by the runtime on `post_job_message`, never by the transport adapter.
export type MessageId = string;

/**
 *  One scheduled pause point as it travels on the wire. The parser
 *  (stage 4) builds one of these per `pause_points:` entry; the
 *  persistence layer (stage 5) writes it into `scheduled_pause_points`
 *  keyed on `(job_id, ordinal)`; the runtime hook (stage 6) reads it
 *  back when checking whether to trip `pause_job`.
 * 
 *  `reason` is the operator's free-text justification, surfaced
 *  verbatim in the chat divider label and in the `StopReason::
 *  ScopedPausePoint` payload. The 512-byte cap is enforced by the
 *  parser, not by this struct — keeping the cap a parse-time rule
 *  lets future iterations relax it without a wire migration.
 */
export type PausePoint = {
	id: PausePointId,
	target: PausePointTarget,
	position: PausePointPosition,
	reason?: string | null,
};

/**
 *  Identity of one scheduled pause point. Defined inline rather than
 *  added to the shared `ulid_newtype!` macro in `id.rs` to keep the
 *  pause-point types one self-contained unit — same rationale
 *  `ScopePatchId` calls out in `scope_patch.rs`.
 */
export type PausePointId = string;

/**
 *  Which side of the targeted boundary the pause fires on. `position:`
 *  is a required YAML key — `pause stage 3` is ambiguous between "halt
 *  before the runner spawns" and "halt after the trio closes", and
 *  forcing the keyword removes the foot-gun (see SCOPED-PAUSE-POINTS
 *  §1.3 and §5 Q1).
 */
export type PausePointPosition = "before" | "after";

/**
 *  What the pause point fires against. `Stage` targets the stage
 *  boundary itself (provisioning side on `Before`, post-trio side on
 *  `After`); `StageTodo` narrows the trigger to one todo inside the
 *  stage. The selector lives on `StageTodo` rather than as a third
 *  `Stage`-variant field so the absence of a selector is a type-level
 *  fact, not a `None` to forget to handle.
 * 
 *  `stage_ordinal` is always the resolved 1-based index into the
 *  template's `stages:` list. Name-form targets (`stage: parser`) are
 *  resolved to an ordinal by the parser before a row reaches this
 *  type, so the wire shape and the SQLite shape match.
 */
export type PausePointTarget = { kind: "stage"; ordinal: number } | { kind: "stage-todo"; stage_ordinal: number; selector: TodoSelector };

/**
 *  Append one message to the per-Job chat thread (`DOCS/JOB-CHAT.md`).
 *  Used by the web chat input, the Telegram and Slack adapters, the
 *  CLI, and the supervisor agent — every voice ends up as one row in
 *  `chat_messages`. The ULID `MessageId` and the `created_at` stamp
 *  are minted server-side so a clock-skewed transport cannot reorder
 *  the thread.
 * 
 *  `external_id` is the transport-native message id (Telegram
 *  `chat:id`, Slack `ts`). Required on Telegram and Slack by SQL
 *  invariant — the partial unique index narrows
 *  `(transport, external_id)` to non-NULL rows, so a redelivered
 *  inbound message would land on a `Conflict` error rather than
 *  double-ingest. Web, CLI, and supervisor rows leave it NULL.
 * 
 *  `role` defaults to `User` because that is the overwhelmingly
 *  common case (every human transport); the supervisor sets it
 *  explicitly to `Assistant`.
 */
export type PostJobMessageArgs = {
	job_id: JobId,
	transport: ChatTransport,
	external_id?: string | null,
	thread_key?: string | null,
	author: string,
	role: ChatRole,
	body: string,
	/**
	 *  Raw transport-extras JSON text (attachments, formatting,
	 *  outbound delivery receipts). Passed through verbatim to the
	 *  `metadata_json` column so the substrate stays opaque per
	 *  `codeless_types::chat::ChatMessage::metadata_json`.
	 */
	metadata_json?: string | null,
};

/**
 *  Result of the Layer-1 diff-verify pre-check the runtime runs
 *  against the prior stage's handover before invoking the REVIEW
 *  model. `Pass` and `Fail` carry the path lists the verifier
 *  resolved so the UI can render the exact set rather than a
 *  boolean glyph; `Skipped` and `NothingToVerify` are split so the
 *  UI can distinguish "no prior handover / git enumeration failed"
 *  from "handover present but no path-shaped tokens to verify"
 *  (the former is a setup gap, the latter is a clean baseline).
 * 
 *  The internal `template_runner::PreCheckOutcome` carries a single
 *  `Fail(String)` and collapses the verified-path list; this wire
 *  variant promotes both halves so the panel renders the actual
 *  paths.
 */
export type PreCheckOutcome = 
/**
 *  Every path the prior handover's `Done` section claimed
 *  resolved to a real diff entry. `verified` is the claimed
 *  path text, in the order the handover listed it.
 */
{ outcome: "pass"; verified: string[] } | 
/**
 *  At least one claimed path was absent from the diff.
 *  `missing` is the claimed-path text for each missing entry,
 *  in the order the handover listed them. The runtime's
 *  `diff_verify::MissingPath` also carries fuzzy candidates
 *  for each miss; this wire shape keeps only the claim text
 *  because the panel surfaces the miss list directly and the
 *  candidates were never reported in the existing log line.
 */
{ outcome: "fail"; missing: string[] } | 
/**
 *  The pre-check could not run: no prior stage on the job, no
 *  worktree on the run context, the prior handover file was
 *  absent, git enumeration failed, or the spawn_blocking task
 *  joined with an error. The runtime treats this identically
 *  to `Pass` (the inner adapter still runs); the wire variant
 *  is kept distinct so the panel renders a setup-gap glyph
 *  rather than a green check.
 */
{ outcome: "skipped" } | 
/**
 *  The pre-check ran and the prior handover's `Done` named no
 *  path-shaped tokens. Distinct from `Skipped` because the
 *  handover was readable and the diff was enumerable; there
 *  was simply nothing the verifier could match against.
 */
{ outcome: "nothing-to-verify" };

/**
 *  One entry in the cross-repo listing — pairs the queue row with the
 *  `RepoId` that owns it so Surface C can group by repo without a
 *  follow-up `list_repos` join.
 */
export type ProposedPatchListEntry = {
	repo_id: RepoId,
	patch: ProposedScopePatch,
};

/**
 *  One unresolved proposal as parsed from `DOCS/SCOPE-PROPOSED.md`.
 *  Wire DTO for `list_proposed_patches` — lifted into `codeless-types`
 *  (R1: mobile shells must see the same shape the host emits) while
 *  the parser / queue-rewriter implementation stays in
 *  `codeless-runtime::scope_patch_queue` (host-only).
 * 
 *  Distinct from [`ScopePatch`]: that struct is the *event* payload
 *  emitted at proposal time and carries `review_id` / `stage_id`
 *  because those are durably linked to the originating REVIEW gate.
 *  `ProposedScopePatch` is the *queue snapshot* — its lifecycle ends
 *  when the human approves or rejects, and only `evidence_stage_id`
 *  (carried by `Loosen` patches as the positive fixture) survives the
 *  markdown round-trip. The two shapes overlap by design but should
 *  not be unified: collapsing them would force the queue file to
 *  carry `review_id` permanently, or force the event to drop it.
 * 
 *  `proposed_at` is the wall-clock time the proposal first landed on
 *  disk. Surface C's "older than 14 days falls below the fold" filter
 *  and the decay sort key off this field — without it, the worklist
 *  view degrades to insertion-order-only. The writer
 *  (`scope_patch_emit::append_to_proposals_file`) stamps it at
 *  proposal-emit time; the reader (`scope_patch_queue::parse_block`)
 *  surfaces it as `Some(_)` for proposals written by the timestamped
 *  writer and `None` for proposals from older writes that predate the
 *  field. The UI treats `None` as "age-unknown" and groups those
 *  after the dated entries rather than rejecting the row.
 */
export type ProposedScopePatch = {
	id: ScopePatchId,
	kind: ScopePatchKind,
	target: ScopePatchTarget,
	target_path: string,
	rationale: string,
	body: string,
	has_predicate: boolean,
	/**
	 *  Set for `Loosen` proposals — names the stage whose diff is the
	 *  positive fixture. `None` for `Tighten`.
	 */
	evidence_stage_id?: StageId | null,
	/**
	 *  Path to the paired predicate file, when the proposal cites one
	 *  (the queue format carries this as a parser-only cross-reference;
	 *  the approval UX surfaces it next to `target_path`).
	 */
	predicate_ref?: string | null,
	/**
	 *  Path to the paired fixture file, when the proposal cites one
	 *  (same shape as `predicate_ref` — used by `Loosen` proposals).
	 */
	fixture_ref?: string | null,
	/**
	 *  Wall-clock time the proposal was appended to
	 *  `DOCS/SCOPE-PROPOSED.md`. `None` for entries written before the
	 *  field existed (legacy data); UI treats unknown ages as
	 *  undated and groups them after dated entries.
	 */
	proposed_at?: UnixMillis | null,
};

/**
 *  Reject a proposed scope patch through the UI. Mirrors `codeless
 *  patches reject`: removes the entry from `DOCS/SCOPE-PROPOSED.md` and
 *  commits the queue edit with a rejection commit body. No rulebook
 *  file is touched. Same idempotence semantics as
 *  `approve_scope_patch`.
 */
export type RejectScopePatchArgs = {
	repo_id: RepoId,
	patch_id: ScopePatchId,
	/**
	 *  Optional free-form rejection reason recorded in the commit body.
	 *  Audit trail only — the runtime does not act on it.
	 */
	reason?: string | null,
};

export type RemoveRepoArgs = {
	repo_id: RepoId,
};

// A managed git repository row — see SCOPE.md Appendix A `repos`.
export type Repo = {
	id: RepoId,
	name: string,
	clone_url: string,
	default_branch: string,
	local_path: string,
	git_auth: GitAuth,
	// `None` means "use the global concurrency cap".
	concurrency_cap: number | null,
	// Runner kind preselected for jobs that don't override it.
	default_runner: string | null,
	created_at: UnixMillis,
	updated_at: UnixMillis,
};

//Identity of a managed git repository row.
export type RepoId = string;

/**
 *  Argument shape for the `reset_job` recovery hatch. A job stuck in
 *  `Queued` (driver kept failing before reaching `Running`), `Failed`,
 *  or `Stopped` is moved back to `Draft` so the operator can edit the
 *  spec or simply re-`start_job` without the resume-cap dance. The
 *  captured worktree (if any) is reaped and `worktree_path` is
 *  cleared; `stop_reason` and `ended_at` are wiped so the row reads
 *  like a fresh draft. Refused for `Running`, `Paused`, `AwaitingReview`,
 *  and `Completed` — those go through `stop_job` / `pause_job` /
 *  `resume_job` instead.
 */
export type ResetJobArgs = {
	job_id: JobId,
};

/**
 *  Undo a previously-applied scope-patch approval by running `git
 *  revert <commit_sha> --no-edit` against the worktree at `repo_id`'s
 *  `local_path`. Used by the patch-inbox's 10-second undo toast
 *  (decision OQ#3): the toast surfaces the approval SHA and a one-click
 *  revert, so changing your mind preserves both events in `git log`.
 * 
 *  Not idempotent — calling twice against the same approval SHA
 *  produces two revert commits, each undoing the prior one. The UI
 *  only exposes this from the transient post-approval toast, so a
 *  double-click in practice means the operator intended the second
 *  revert.
 */
export type RevertScopePatchArgs = {
	repo_id: RepoId,
	/**
	 *  SHA of the approval commit the operator wants to undo. Returned
	 *  on the matching `ScopePatchActionResult::Approved { commit_sha }`
	 *  from the prior `approve_scope_patch` call.
	 */
	commit_sha: string,
};

/**
 *  Outcome of `revert_scope_patch`. Separate from
 *  `ScopePatchActionResult` because revert has no `AlreadyResolved`
 *  shape — calling it after the approval has itself been reverted just
 *  produces another revert commit.
 */
export type RevertScopePatchResult = {
	// SHA of the new revert commit on the current branch.
	commit_sha: string,
};

// A review row attached to a stage — see SCOPE.md Appendix A `reviews`.
export type Review = {
	id: ReviewId,
	stage_id: StageId,
	status: ReviewStatus,
	comment: string | null,
	requested_at: UnixMillis,
	resolved_at: UnixMillis | null,
};

//Identity of a review gate attached to a stage.
export type ReviewId = string;

/**
 *  Review-gate lifecycle. Reviews are a *state* on a Stage, not a node
 *  in the tree (SCOPE.md "Tasks are the atomic re-runnable unit. Stages
 *  are the verify-gated unit. Reviews are gates, not nodes…").
 */
export type ReviewStatus = "pending" | "approved" | "rejected" | "stopped" | "rerun-requested";

/**
 *  REVIEW-stage verdict surfaced on the event bus. The runtime
 *  keeps its own `ReviewVerdict` next to the sentinel parser; this
 *  wire variant adds `AutoFail` for the cases where the model was
 *  never invoked (pre-check rejected the stage) or where the
 *  post-stage validator rejected the gate before the verdict could
 *  be acted on (sentinel unparseable, scope-patch validation
 *  failed). The reason text mirrors what the matching `tracing`
 *  call already records, verbatim.
 */
export type ReviewVerdict = 
/**
 *  The model wrote a `PASS:` sentinel and downstream patch
 *  validation accepted the handover.
 */
{ verdict: "pass"; reason: string } | 
// The model wrote a `FAIL:` sentinel.
{ verdict: "fail"; reason: string } | 
/**
 *  The runtime closed the gate without (or in spite of) the
 *  model's verdict: pre-check fail, sentinel missing /
 *  ambiguous, or scope-patch validation rejected.
 */
{ verdict: "auto-fail"; reason: string };

/**
 *  One entry in `ServerInfo.runners`. The `id` matches the runner key
 *  the driver dispatches on (`mock`, `claude`, `anthropic`); the UI
 *  uses it as the value submitted in `SubmitJobArgs.runner`. `default`
 *  flags the runner the UI should pre-select when opening the submit
 *  dialog — the server picks at most one, with a stable preference for
 *  real runners over the mock so a freshly-`--enable-claude` server
 *  does not silently default new jobs to the demo path.
 */
export type RunnerInfo = {
	id: string,
	default: boolean,
};

/**
 *  One patch proposal — the structured form of a single suggested
 *  edit to the rulebook. Read by humans via `DOCS/SCOPE-PROPOSED.md`
 *  and by automated consumers via the matching `ScopePatchProposed`
 *  event.
 * 
 *  Field invariants honoured by the *parser* (Step 5; not enforced at
 *  this struct's level so a Step 4 shadow-mode emit can land with a
 *  partially-populated proposal and still be observable):
 * 
 *  - `has_predicate = true` requires `kind == Tighten` and a paired
 *    predicate file in the same human commit when the patch is
 *    approved.
 *  - `evidence_stage_id = Some(_)` requires `kind == Loosen` and
 *    names a stage whose diff exhibits the positive fixture.
 *  - `kind == Tighten` ⇒ `evidence_stage_id` is `None`.
 *  - `kind == Loosen` ⇒ `evidence_stage_id` is `Some(_)` and
 *    `has_predicate` is `false`.
 * 
 *  `body` carries the literal text the patch would apply (a unified
 *  diff snippet, a replacement sentence, or a "delete the paragraph
 *  matching ..." instruction). The Step 6 approval UX shows it
 *  verbatim; the runtime does not parse it.
 */
export type ScopePatch = {
	id: ScopePatchId,
	/**
	 *  The REVIEW stage that emitted the proposal. Pairs the proposal
	 *  with the `ReviewRequested` / `ReviewApproved` envelopes the UI
	 *  already renders.
	 */
	review_id: ReviewId,
	/**
	 *  The stage that ran the REVIEW. Same value travels on the
	 *  `ScopePatchProposed` event's `stage_id` field.
	 */
	stage_id: StageId,
	kind: ScopePatchKind,
	target: ScopePatchTarget,
	/**
	 *  Repo-relative path of the file the patch proposes to edit.
	 *  Step 5 cross-checks this against the mutable-set list in
	 *  `rule_bearing_files`; Step 6 displays it.
	 */
	target_path: string,
	/**
	 *  One-sentence justification the REVIEW model wrote alongside
	 *  the `PASS:` sentinel. The approval UX surfaces it as the
	 *  proposal's title; do not stuff prose here.
	 */
	rationale: string,
	/**
	 *  The literal edit body (diff fragment, replacement text, or
	 *  delete-this-paragraph instruction). Free-form on the wire;
	 *  the human-authored approval commit interprets it.
	 */
	body: string,
	/**
	 *  True ⇒ a predicate file landed in the same proposal. Required
	 *  for `Tighten` once Step 5 enforcement is live; carried on the
	 *  envelope so the approval UX can group "patch + predicate"
	 *  proposals together without re-reading the body.
	 */
	has_predicate: boolean,
	/**
	 *  For `Loosen`: the stage whose diff is the positive fixture.
	 *  `None` on `Tighten`; `Some` on `Loosen` once Step 5 lands.
	 *  Optional in Step 4 shadow mode so partial proposals are
	 *  observable on the wire and the parse-time rejection can name
	 *  the missing field by Step 5.
	 */
	evidence_stage_id: StageId | null,
};

/**
 *  Outcome of an `approve_scope_patch` / `reject_scope_patch` /
 *  `edit_scope_patch` call. The same wire shape is returned by all
 *  three so the UI's idempotency handling code path stays uniform:
 *  `AlreadyResolved` is a successful response, not an error, and the
 *  UI swaps its row to the resolved view without a toast.
 */
export type ScopePatchActionResult = 
/**
 *  `approve_scope_patch` produced a human-authored approval commit.
 *  `commit_sha` is the SHA of the new commit, suitable for linking
 *  to a `commit/<sha>` route.
 */
{ outcome: "approved"; commit_sha: string } | 
// `reject_scope_patch` produced a rejection commit.
{ outcome: "rejected"; commit_sha: string } | 
/**
 *  `edit_scope_patch` rewrote the queue entry. No commit is
 *  produced — `edit` is a pre-approval ergonomic.
 */
{ outcome: "edited" } | 
/**
 *  The patch had already been resolved by a previous call (possibly
 *  from another window, possibly from the CLI). `resolution`
 *  distinguishes approved vs rejected; `commit_sha` carries the
 *  SHA of the existing resolution commit when the runtime could
 *  locate it in `git log`, `None` when the commit predates the
 *  markers the runtime greps for (legacy approvals).
 */
{ outcome: "already_resolved"; resolution: ScopePatchResolution; commit_sha?: string | null };

/**
 *  Identity of one `ScopePatch` proposal. ULID for the same reason
 *  every other identity in `codeless-types::id` is a ULID: monotonic
 *  over a session, sortable by creation order, and unambiguous on the
 *  wire. Defined here rather than in `id.rs` because adding it to the
 *  shared `ulid_newtype!` macro would force every consumer (mobile
 *  included) to depend on the macro the moment a `ScopePatchId`
 *  imports — keeping it in this module keeps the patch types one
 *  logical unit.
 */
export type ScopePatchId = string;

/**
 *  Whether a patch makes a rule stricter (`Tighten`) or weaker
 *  (`Loosen`). Per `SESSION-MUTABLE-SCOPE-DECISIONS.md` Q2, rule
 *  *removal* is `Loosen`: after the patch lands the rule no longer
 *  constrains, which is observably the same effect as a
 *  textually-narrower replacement. Predicate-file deletion is **not**
 *  a third kind — it rides on a paired `Loosen` patch in the
 *  approving human's commit (decisions Q5).
 */
export type ScopePatchKind = "tighten" | "loosen";

/**
 *  Which terminal state a previously-acted-on patch ended up in. Used
 *  by `ScopePatchActionResult::AlreadyResolved` so a stale UI window
 *  can render the right "this patch was {approved,rejected} by another
 *  window" message without a follow-up RPC.
 */
export type ScopePatchResolution = "approved" | "rejected";

/**
 *  Which rulebook surface the patch proposes to change. The enum
 *  names the *category* the surface belongs to; the exact file path
 *  travels separately on the `ScopePatch.target_path` field so the
 *  human approval UX in Step 6 can show "this proposal edits
 *  `.codeless/jobs/foo/SCOPE.md`" without needing a per-job variant
 *  here.
 * 
 *  The mutable-set vs wire-format-set distinction in
 *  `codeless-runtime::rule_bearing_files` is enforced at parse time
 *  in Step 5; this enum lists only categories that are members of the
 *  mutable set. Wire-format files (`DOCS/JOB-MODEL.md`,
 *  `DOCS/JOB-LOOP.md`, `codeless-types/src/handover.rs`) have no
 *  variant here on purpose — proposing a patch against one is a
 *  parse-time reject.
 */
export type ScopePatchTarget = 
// Workspace-level `CLAUDE.md` or the inner repo's `CLAUDE.md`.
"claude-md" | 
// A per-job `SCOPE.md` under `.codeless/jobs/<name>/`.
"job-scope-md" | 
// A per-job `WORKFLOW.md` under `.codeless/jobs/<name>/`.
"job-workflow-md" | 
/**
 *  A per-job `CLAUDE.md` under `.codeless/jobs/<name>/` (only
 *  some jobs ship one; the variant is present so a future job
 *  that does can still surface patches).
 */
"job-claude-md";

/**
 *  Capability bits the runtime advertises to the UI at boot. Each
 *  flag is `false` by default and flips to `true` only when the
 *  runtime can guarantee the corresponding behaviour end-to-end.
 *  Whoever lands the runtime support also flips the flag, in the
 *  same change, so the UI never has to special-case "flag exists
 *  but the underlying behaviour is half-built".
 */
export type ServerFeatureFlags = {
	/**
	 *  `true` once the handover writer round-trips
	 *  `<!-- SCOPE-PATCH-BEGIN ... -->` / `<!-- SCOPE-PATCH-END -->`
	 *  markers without dropping or rewriting them — the precondition
	 *  for the SESSION-MUTABLE-SCOPE patch flow to surface in the UI.
	 *  Surface A's "Patches proposed: N" counter row is omitted while
	 *  this is `false`, on the principle from
	 *  `DOCS/SCOPE-MUTABLE-UI-DECISIONS.md` OQ#1 that a counter row
	 *  gated on a half-built capability would lie. Step 2 of the
	 *  scope-mutable-ui ramp lands the handover-schema fix and flips
	 *  this to `true` from `build_server_info`.
	 */
	scope_patch_handover_round_trip?: boolean,
};

/**
 *  `GET /server/info` payload. Sits outside the bearer gate alongside
 *  `/healthz` and `/version` — the UI must reach it before the user
 *  can supply a token, since the runner dropdown and "demo mode"
 *  banner both depend on it. No mutable runtime state leaks here; it
 *  is a snapshot of how `codeless serve` was configured.
 */
export type ServerInfo = {
	version: string,
	runners: RunnerInfo[],
	/**
	 *  Frozen at boot to the `--fs-root` flag the operator launched
	 *  `codeless serve` with (or `None` when the flag was omitted). Does
	 *  **not** track the live `attached_workspaces` set: attaching or
	 *  detaching a workspace at runtime never rewrites this field, so
	 *  the UI must read `list_workspaces` for the active roster. The
	 *  field stays in `ServerInfo` because some shells (the bootstrap
	 *  banner, the demo-mode hint) need the boot-time path before any
	 *  authenticated RPC has run.
	 */
	fs_root: string | null,
	worktree_root: string | null,
	/**
	 *  `Some` when the `claude` runner is enabled and the host probe
	 *  ran. The probe is cheap (one `--version` invocation plus an
	 *  optional 2 s auth check) so it runs once at boot; the UI need
	 *  not poll. `None` when the runner is disabled — the settings
	 *  surface renders an "enable with --enable-claude" hint instead.
	 */
	claude: ClaudeStatus | null,
	/**
	 *  CLI coder runners (`claude`, `codex`, `copilot`) the host has
	 *  probed and found ready — binary discoverable, basic auth state
	 *  surface-able. The footer agent panel reads this to filter its
	 *  model dropdown so the user never picks a runner that will
	 *  immediately fail. Probed once at boot via `Runner::ready`;
	 *  re-launch the server to refresh after installing a new CLI.
	 */
	available_cli_runners?: string[],
	/**
	 *  Boot-time capability flags. The runtime sets each flag once
	 *  the underlying capability is real; the UI gates surfaces on
	 *  the corresponding flag rather than shipping a row that may
	 *  silently lie when the runtime side has not yet landed. New
	 *  flags must default to `false` so older runtimes parse a
	 *  shorter payload as "capability absent" rather than missing
	 *  the field and crashing the UI deserialisation.
	 */
	feature_flags?: ServerFeatureFlags,
	/**
	 *  Loopback REST endpoint exposed alongside this runtime. The
	 *  Tauri desktop shell embeds `codeless-server` on an ephemeral
	 *  `127.0.0.1` port so external tools (scripts, AI agents) can
	 *  reach the same in-process runtime over HTTP without spawning a
	 *  second `codeless serve`. `None` for hosts that do not expose a
	 *  REST surface (the bare `codeless serve` path leaves this
	 *  `None` because the server itself *is* the REST surface and the
	 *  bind address is already public in its launch banner).
	 */
	rest_url?: string | null,
};

// A verify-gated chunk of a job — see SCOPE.md Appendix A `stages`.
export type Stage = {
	id: StageId,
	job_id: JobId,
	ordinal: number,
	name: string,
	status: StageStatus,
	// `None` when this stage has no verify gate.
	verify_cmd: string | null,
	started_at: UnixMillis | null,
	ended_at: UnixMillis | null,
	/**
	 *  Runner-supplied session identifier, captured the first time a
	 *  task on this stage reports a non-empty `RunResult.session_id`.
	 *  Free-form on the wire — Claude emits `sess-<ulid>`, other
	 *  runners may use a different shape. `None` until a task
	 *  reports one; never cleared once set, and never reused by a
	 *  later stage (per SCOPE.md hard rule #1, the stage is the
	 *  session boundary). Subsequent tasks within the **same** stage
	 *  resume this session via `--continue <session_id>` — that is
	 *  what makes pause / resume / cap-bump inside a stage feel like
	 *  a continuous Claude Code conversation rather than a fresh
	 *  codebase-exploration every time.
	 */
	session_id: string | null,
	/**
	 *  One-sentence statement of what success for this stage means.
	 *  Authored in the per-stage docs; surfaced in the UI overview so
	 *  the reader doesn't have to open the stage doc to remember the
	 *  intent. `None` for stages authored before the field existed.
	 */
	goal?: string | null,
	/**
	 *  Acceptance criteria bullets, in author order. The UI renders
	 *  each as a tickable line so the human reviewer can match output
	 *  against the contract the stage was written to. `None` (not
	 *  `Some(vec![])`) for stages authored before the field existed
	 *  so a missing list and a deliberately empty list stay
	 *  distinguishable.
	 */
	acceptance?: string[] | null,
	/**
	 *  Wall-clock millis of the last activity observed on this stage's
	 *  warm session (turn start, user message, sweeper tick). `None`
	 *  when the stage has never had a session captured. Used by the
	 *  runtime's idle-timeout sweeper to decide when to archive the
	 *  session so a paused/failed stage does not hold a runner
	 *  subprocess open forever; see `session_idle` module.
	 */
	last_activity_at?: UnixMillis | null,
	/**
	 *  `true` once the warm session has been archived (idle timeout
	 *  elapsed or explicit `archive_session` RPC). One-way flag: the
	 *  next user message against this stage opens a fresh session with
	 *  a handover document rather than resuming the recorded
	 *  `session_id`. The captured id is preserved on the row for
	 *  audit / UI labelling of the archived turn.
	 */
	archived?: boolean,
	/**
	 *  Persona id this stage runs under. NULL means the stage
	 *  inherits the job-level persona (`jobs.persona_id`); a populated
	 *  value is the result of the per-stage `persona:` YAML override
	 *  resolved at job-submit time (AGENT-DECISIONS.md D1). The column
	 *  is recorded on the row so a re-run reproduces the same persona
	 *  the stage originally ran under even if the user later edited
	 *  the template or the persona row.
	 */
	persona_id?: string | null,
	/**
	 *  Wall-clock millis the operator (or a future auto-bypass
	 *  policy) marked this stage as bypassed. `None` is the
	 *  common case; `Some(_)` together with `status: Failed`
	 *  means "advance past this stage on the next run." The
	 *  status column stays `Failed` so the audit trail keeps
	 *  the original outcome; the bypass timestamp is the
	 *  forward-advance signal.
	 */
	bypassed_at?: UnixMillis | null,
	/**
	 *  Operator (or policy) reason for the bypass. Free-text;
	 *  rendered in the run log + the UI gate panel so the audit
	 *  trail names *why* the bypass happened. `None` when
	 *  `bypassed_at` is also `None`.
	 */
	bypassed_reason?: string | null,
	/**
	 *  Coarse machine-readable classification of *why* this stage
	 *  ended `Failed`. `None` when `status != Failed` and on rows
	 *  written before the column existed; the UI treats `None +
	 *  Failed` as "legacy / unclassified failure" and falls back to
	 *  the event stream. See `FailureClass` for the variant
	 *  contract.
	 */
	failure_class?: FailureClass | null,
	/**
	 *  Short human-readable failure description (one line, ~200
	 *  chars). Typically the runner's reason string, the REVIEW
	 *  model's FAIL reason, or the pre-check validator's error.
	 *  Truncated by the writer if the source is longer; the full
	 *  transcript stays on disk. `None` when no detail was captured
	 *  or when `status != Failed`.
	 */
	failure_detail?: string | null,
};

//Identity of a verify-gated chunk within a job.
export type StageId = string;

// Stage lifecycle. Matches `stages.status` wire labels.
export type StageStatus = "pending" | "running" | "awaiting-review" | "passed" | "failed";

export type StartJobArgs = {
	job_id: JobId,
};

/**
 *  Stop *whatever* is currently running for `job_id`: the job runner
 *  (when the row is `Running` / `AwaitingReview` / `Queued`), every
 *  in-flight chat turn whose `session_id` is this job, or both. The
 *  umbrella around `stop_job` + `cancel_chat_task` so the UI's stop
 *  button has a single endpoint to call regardless of which spawn
 *  path is alive. Idempotent — neither path firing is `Ok(())` with
 *  `stopped_job: false` and an empty `cancelled_chat_task_ids`.
 */
export type StopActiveArgs = {
	job_id: JobId,
};

/**
 *  What `stop_active` actually did. The UI uses this to surface a
 *  "stopped the chat turn" / "stopped the job" / "stopped both" /
 *  "nothing was running" status without a second round-trip.
 */
export type StopActiveResult = {
	/**
	 *  `true` when the umbrella issued `stop_job` against a row in
	 *  `Running` / `AwaitingReview` / `Queued`. `false` when the row
	 *  was already terminal (or paused), so only the chat side could
	 *  possibly have fired.
	 */
	stopped_job: boolean,
	/**
	 *  Per-turn `TaskId`s whose cancel tokens were fired. Empty when
	 *  no chat turn was scoped to this job at call time.
	 */
	cancelled_chat_task_ids: TaskId[],
};

export type StopJobArgs = {
	job_id: JobId,
};

/**
 *  Why a job left the running set early. `None` while running or after a
 *  clean completion; populated when status is `Stopped` or `Failed`.
 */
export type StopReason = "user" | "cost-cap" | "wall-clock" | "runner-crash" | 
/**
 *  Surface F thrashing guard: the per-job `AutoBypassPolicy` fired
 *  twice in a row with no `Passed` stage between, so the runtime
 *  halts the job instead of auto-bypassing a third time. The
 *  guidance comment thread converged on nothing in two attempts;
 *  a third would burn more tokens for the same outcome. See
 *  `DOCS/AUTO-BYPASS-DECISIONS.md` Q1 — two-strikes is the
 *  canonical window size, written here as the wire-level stop
 *  reason so the UI can render `policy thrashing` distinctly from
 *  the other terminal causes.
 */
"auto-bypass-thrashing" | 
/**
 *  A REVIEW stage's structural diff-verify pre-check rejected the
 *  prior stage's handover before the model ran. Distinct from
 *  `RunnerCrash` because the runner never executed: a plain
 *  resume re-runs the same deterministic pre-check against the
 *  same handover and fails identically. The recovery path is the
 *  explicit `override_pre_check_and_resume` RPC, which requires
 *  the operator to acknowledge the gap and supply a comment that
 *  threads into the stage prompt; the override is a one-shot
 *  audit-logged opt-in, not a sticky flag.
 */
"review-pre-check" | 
/**
 *  A pre-declared scope-level pause point (operator-authored in
 *  `template.yaml`) fired. Distinct from `User` so the chat and
 *  dashboard can render a "planned pause" divider instead of a
 *  runtime-pause chip, and the divider lookup can carry the
 *  `point_id` back to the `scheduled_pause_points` row for
 *  `reason` text. Resumes through the existing `resume_job` RPC;
 *  cost-cap behaviour is identical to `User` per SCOPED-PAUSE-
 *  POINTS §5 Q4.
 */
{ "scoped-pause-point": { "point-id": PausePointId } };

export type StopReviewArgs = {
	review_id: ReviewId,
};

export type SubmitJobArgs = {
	repo_id: RepoId,
	prompt: string | null,
	template_yaml: string | null,
	runner: string,
	branch: string,
	/**
	 *  `in_repo` (default) edits the user's local clone; `worktree`
	 *  creates a separate `git worktree add` checkout. Omit or `null`
	 *  to get the default (`in_repo`).
	 */
	workspace_mode?: WorkspaceMode | null,
	cost_cap_cents: number,
	wall_clock_cap_ms: number,
	/**
	 *  Per-job runner overrides. All three are optional and round-trip
	 *  onto `Job` so re-runs inherit the original settings. Adapters
	 *  silently ignore knobs they do not support (Copilot has no
	 *  `permission_mode` or `effort`, for example).
	 */
	model?: string | null,
	permission_mode?: string | null,
	effort?: string | null,
	/**
	 *  Persona-derived system prompt composed by the caller (UI, CLI)
	 *  and applied to every stage of the job. The UI fills this from
	 *  the selected persona's `instructions` when the user picks one
	 *  from the job-submit dropdown; `None` keeps the server's
	 *  configured default. A future stage replaces this with a
	 *  `persona_id` lookup against a server-side persona table; until
	 *  then the composed text travels on the submit args and is
	 *  persisted on the job row so reruns and resumes reproduce it.
	 */
	system_prompt?: string | null,
	/**
	 *  Persona the user picked at submit time. The composed prompt
	 *  still travels on `system_prompt`; this is the lookup key that
	 *  produced it. The runtime persists it verbatim onto the job row
	 *  so a rerun can reproduce the same agent posture. `None` means
	 *  the user submitted without picking a persona. Personas live in
	 *  the UI KV store today, so the field is a free string; the FK
	 *  against a server-side persona table lands in a later stage.
	 */
	persona_id?: string | null,
	/**
	 *  Per-job auto-bypass policy (Surface F). `None` (default) keeps
	 *  the existing halt-on-failure behaviour; `Some(...)` pre-
	 *  authorises the runtime to advance past a failed stage under
	 *  the chosen preset's canned guidance (or a custom comment).
	 *  The value is persisted onto the `Job` row verbatim so a
	 *  resume / rerun reproduces the same policy.
	 */
	auto_bypass_policy?: AutoBypassPolicy | null,
	/**
	 *  `false` (default) lands the job in `Draft` status — the row
	 *  exists, the user can edit the spec / docs / handover, but the
	 *  driver does not pick it up. The user calls `start_job` to
	 *  promote `Draft → Queued`. `true` (legacy / power-user behaviour)
	 *  skips the draft state and lands directly in `Queued` so the
	 *  driver runs immediately.
	 */
	start_immediately?: boolean,
};

/**
 *  The atomic re-runnable unit inside a stage — see SCOPE.md Appendix A
 *  `tasks`. `depends_on` carries DAG edges from day one so the event
 *  schema is forward-compatible with topological execution (SCOPE.md
 *  Rule 4); linear-mode runtimes leave it empty.
 */
export type Task = {
	id: TaskId,
	stage_id: StageId,
	ordinal: number,
	status: TaskStatus,
	depends_on: TaskId[],
	/**
	 *  `"<pid>:<startup-nonce>"` while leased; `None` while idle. The
	 *  startup-nonce is minted once per core-process start so PID-reuse
	 *  after a crash can't be mistaken for an alive holder.
	 */
	lease_holder: string | null,
	lease_expires_at: UnixMillis | null,
	cost_cents: CostCents,
	input_tokens: number,
	output_tokens: number,
	started_at: UnixMillis | null,
	ended_at: UnixMillis | null,
};

//Identity of one atomic runner invocation within a stage.
export type TaskId = string;

// Task lifecycle. Matches `tasks.status` wire labels.
export type TaskStatus = "enqueued" | "running" | "completed" | "failed" | "cancelled";

//Identity of one user-visible sub-step within a task (`todos` row).
export type TodoId = string;

/**
 *  Origin of a todo. The closing trio (`Checks`, `Docs`, `Git`) is
 *  runtime-injected so a misbehaving runner cannot silently skip it;
 *  `Runner` items come from the runner's own plan tool (`TodoWrite`
 *  for Claude Code, equivalent for Codex). `Planner` items are reserved
 *  for the future planner-driven path where the stage's checklist is
 *  declared up-front rather than discovered as the runner works.
 */
export type TodoKind = "runner" | "planner" | "checks" | "docs" | "git";

/**
 *  How a todo inside a stage is named. `Ordinal` is a 1-based index
 *  into the stage's todo list at trigger time; `Trio` names one of the
 *  runtime-injected closing-trio kinds (always resolvable at submit
 *  time); `TitleSubstring` is a case-insensitive `contains` match
 *  evaluated at trigger time so runner-authored todos that don't exist
 *  at parse time can still be addressed.
 * 
 *  Trio kinds are reserved words at the YAML layer: `todo: checks`
 *  always resolves to `Trio(Checks)`, even if a runner-authored todo
 *  happens to share the title. To target a non-trio todo whose title
 *  contains a trio word, use `~checks` (the substring form) — see
 *  SCOPED-PAUSE-POINTS §1.2.3.
 */
export type TodoSelector = { selector: "ordinal"; ordinal: number } | { selector: "trio"; kind: TodoKind } | { selector: "title-substring"; pattern: string };

/**
 *  Todo lifecycle. `Skipped` is a terminal "did not run, will not run"
 *  state distinct from `Failed` — used for the `git` trio item when a
 *  stage produced no diff, and for any planner-injected item the runner
 *  resolved away (e.g. an investigation that proved unnecessary).
 */
export type TodoStatus = "pending" | "in-progress" | "done" | "skipped" | "failed";

/**
 *  Unix-milliseconds, UTC. Matches the `INTEGER` timestamp columns in
 *  `DOCS/SCOPE.md` Appendix A. Stored as `i64` rather than `u64` so SQLite
 *  `INTEGER` round-trips with `sqlx` (which surfaces signed integers).
 */
export type UnixMillis = number;

/**
 *  Record one transport's outbound delivery receipt against a
 *  `chat_messages` row. Called by the Telegram / Slack outbound
 *  forwarders after a successful platform send so the next event-bus
 *  fan-out (after a restart, or to a second forwarder on the same
 *  transport) can presence-check `metadata_json.delivery.<transport>`
 *  and skip the duplicate post. Per `JOB-CHAT.md` "Transport adapters"
 *  the column owners that the runtime guarantees never to overwrite —
 *  `body` and `external_id` — stay immutable; only `metadata_json` is
 *  mutated, and even there only the substrate-owned `delivery.<transport>`
 *  key is touched (OQ-CHAT-5 §metadata keyspace).
 * 
 *  `platform_id` is the id the platform returned for the *outbound*
 *  send (Telegram `message_id`, Slack `ts`) — NOT the originating
 *  transport's `external_id`. Mixing the two would conflate the source
 *  of truth with the delivery receipt; the immutability bias in
 *  JOB-CHAT.md exists exactly to keep that line clean.
 */
export type UpdateChatMessageDeliveryArgs = {
	message_id: MessageId,
	transport: ChatTransport,
	platform_id: string,
};

/**
 *  `assistant.uploadAttachment`. Drop a binary blob into a thread's
 *  attachments directory under
 *  `<codeless-data>/threads/<thread_id>/attachments/<id>-<filename>`
 *  and insert the index row. The UI references the returned
 *  `AssistantAttachment.id` in subsequent turns; the model reads the
 *  file from a path the runtime resolves server-side, so the wire
 *  never carries a host filesystem path.
 * 
 *  `NotFound` for an unknown thread; `InvalidArgument` for a filename
 *  that fails the basename sanitiser or an undecodable base64 body;
 *  `Internal` when the runtime has no `<codeless-data>` root
 *  configured (tests that omit `with_assistant_data_dir`).
 */
export type UploadAssistantAttachmentArgs = {
	thread_id: AssistantThreadId,
	// Basename only — directory components are stripped server-side.
	filename: string,
	/**
	 *  Standard base64 (with or without padding). Decoded server-side;
	 *  invalid input returns `InvalidArgument`.
	 */
	content_b64: string,
	/**
	 *  Optional MIME type the UI sniffed at drop time. Surfaced back
	 *  to the model in the chat preamble so it can pick the right
	 *  reading strategy when the runner supports it.
	 */
	mime_type?: string | null,
};

export type UploadAssistantAttachmentResult = {
	attachment: AssistantAttachment,
};

/**
 *  Drop a binary blob (image, PDF, csv, …) into the job worktree
 *  under `.codeless/chat-attachments/` so the next `agent_chat` turn
 *  can reference it by path. Files are written with a unique prefix
 *  (millis + counter) to avoid collisions and are NOT git-committed —
 *  they are out-of-band scratch input for the CLI runner running in
 *  the worktree cwd.
 * 
 *  Returns `Conflict` if the job has no worktree yet (runner has not
 *  run); the UI surfaces this as "submit the job first".
 */
export type UploadChatAttachmentArgs = {
	job_id: JobId,
	/**
	 *  Basename only — directory components are stripped. Sanitised
	 *  server-side; the original is kept as the suffix after the
	 *  unique prefix so the filename is recognisable to the model.
	 */
	filename: string,
	/**
	 *  Standard base64 (with or without padding). Decoded server-side;
	 *  invalid input returns `InvalidArgument`.
	 */
	content_b64: string,
};

export type UploadChatAttachmentResult = {
	/**
	 *  Path relative to the job worktree root, e.g.
	 *  `.codeless/chat-attachments/1700000000000-0-screenshot.png`.
	 *  The UI references this in the chat prompt so the CLI runner,
	 *  invoked with the worktree as cwd, can read it directly.
	 */
	relative_path: string,
	/**
	 *  Absolute path on the server host. Surfaced for parity with
	 *  `write_handover`; UI does not need it for the chat flow but
	 *  may show it in a tooltip.
	 */
	absolute_path: string,
};

export type UserPromptSnippet = {
	/**
	 *  Short label the UI showed the user when they opted in (e.g.
	 *  `repo conventions`). Rendered as the block heading in the
	 *  preamble.
	 */
	label: string,
	// Snippet body. Markdown is allowed; the runtime emits it as-is.
	body: string,
};

export type ValidateWorkspacePathArgs = {
	path: string,
};

/**
 *  Dry-run path validation for the workspace picker. Every field is
 *  independent so the UI can render the row even when the path
 *  resolves but fails one of the structural checks.
 */
export type ValidateWorkspacePathResult = {
	/**
	 *  `None` when the path could not be resolved at all (does not
	 *  exist, traversal blocked, etc). Populated even when problems
	 *  are present so the UI can show what the server saw.
	 */
	canonical: string | null,
	is_dir: boolean,
	is_git_repo: boolean,
	default_branch: string | null,
	already_attached: boolean,
	readable: boolean,
	writable: boolean,
	problems: WorkspaceProblem[],
};

/**
 *  Structured failure modes for attach/detach. Wire-distinct from a
 *  generic `Conflict` so the UI can branch on the variant — e.g.
 *  `RunningJobs` triggers the "stop jobs?" modal without parsing a
 *  human-readable string.
 */
export type WorkspaceError = { "already-attached": { "repo-id": RepoId; "fs-root": string } } | { "running-jobs": { jobs: JobId[] } } | { "path-rejected": { problems: WorkspaceProblem[] } } | "not-attached";

// Where the agent's edits land. See SCOPE.md "Workspace mode".
export type WorkspaceMode = 
// Edits land in the user's existing local clone on a fresh branch.
"in-repo" | 
// Edits land in a separate `git worktree add` checkout.
"worktree";

/**
 *  Structured reason a candidate workspace path is unusable. The UI
 *  renders each variant inline rather than string-matching on a
 *  generic error message.
 */
export type WorkspaceProblem = "not-a-directory" | "not-readable" | "not-writable" | "not-a-git-repo" | { "inside-another-workspace": { "other-root": string } } | 
/**
 *  `/`, `/etc`, `/usr`, `~/.ssh`, `$HOME` without a subdir, etc.
 *  Hard refusal regardless of user override.
 */
"system-path" | "symlink-outside-home";
